from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class NrdrbPdcpParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        if self.is_sa_nsa:
            if self.mo_num == '1':
                self.set_parameter('tReorderingDl', 'ms100')
                self.set_parameter('tReorderingUl', 'ms100')
                self.set_parameter('xxFlowControlProfForCuIdx', '1')
            elif self.mo_num == '2':
                self.set_parameter('tReorderingDl', 'ms100')
            elif self.mo_num == '3':
                self.set_parameter('pdcpBufDiscardEnabled', 'false')
                self.set_parameter('tReorderingDl', 'ms100')

        if self.is_sa:
            if self.mo_num == '1':
                self.set_parameter('maxCidAllowed', '4')
                self.set_parameter('tReorderingUl', 'ms300')
                self.set_parameter('xxFlowControlProfForCuIdx', '1')
            elif self.mo_num == '2':
                self.set_parameter('maxCidAllowed', '4')
                self.set_parameter('xxFlowControlProfForCuIdx', '1')
            elif self.mo_num == '3':
                self.set_parameter('pdcpBufDiscardEnabled', 'false')
                self.set_parameter('xxFlowControlProfForCuIdx', '1')
